subsections.syntax:
class ClassName:
    '''docstring'''
    class_attribute = value

    def __init__(self, parameters):
        self.instance_attribute = value

    def method(self, ...):
        ...

examples:
class Dog:
    species = 'Canis familiaris'

    def __init__(self, name, age):
        self.name = name
        self.age = age

    def bark(self):
        return f'{self.name} говорит Гав!'

buddy = Dog('Бадди', 5)
print(buddy.bark())

class Animal:
